from datetime import timedelta

# Test if timedelta creation itself raises OverflowError
try:
    td = timedelta(seconds=1e308)
    print(f"Created timedelta: {td}")
except OverflowError as e:
    print(f"OverflowError during timedelta creation: {e}")

# Try with int
try:
    result = 1e308
    td2 = timedelta(seconds=result)
    print(f"Created timedelta from float: {td2}")
except OverflowError as e:
    print(f"OverflowError during timedelta creation from float: {e}")

# Try smaller but still large value
for exp in [300, 305, 306, 307, 308, 309]:
    try:
        td = timedelta(seconds=10**exp)
        print(f"10^{exp}: OK")
    except OverflowError:
        print(f"10^{exp}: OverflowError")
EOF
